const input = $input.first().json;
const body = input.body || input;

const LEAD_MINUTES = 70;
const BUSINESS_TIME_ZONE = 'America/Sao_Paulo';
const limpar = (valor, limite = 500) => valor ? String(valor).trim().slice(0, limite) : '';

function getBusinessNow() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: BUSINESS_TIME_ZONE,
    year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false, hourCycle: 'h23',
  }).formatToParts(new Date());
  const v = (type) => parts.find((p) => p.type === type)?.value;
  return { date: `${v('year')}-${v('month')}-${v('day')}`, time: `${v('hour')}:${v('minute')}` };
}

function timeToMinutes(timeValue) {
  const [h, m] = String(timeValue || '').slice(0, 5).split(':').map(Number);
  return Number.isFinite(h) && Number.isFinite(m) ? h * 60 + m : null;
}

function isTooSoonOrPast(dateValue, timeValue) {
  const now = getBusinessNow();
  if (dateValue < now.date) return true;
  if (dateValue > now.date) return false;
  const slotMinutes = timeToMinutes(timeValue);
  const nowMinutes = timeToMinutes(now.time);
  return slotMinutes === null || slotMinutes < nowMinutes + LEAD_MINUTES;
}

const payload = {
  id_agendamento: limpar(body.id_agendamento || `MRJ-${Date.now()}`, 40),
  nome_cliente: limpar(body.nome_cliente || body.name || body.nome, 200),
  telefone: limpar(body.telefone || body.phone || body.whatsapp, 40),
  whatsapp: limpar(body.whatsapp, 40),
  email: limpar(body.email, 180),
  telegram: limpar(body.telegram, 120),
  servico: limpar(body.servico || body.service, 180),
  duracao_media: Number(body.duracao_media || body.duration || 50),
  valor_referencia: body.valor_referencia || body.price || null,
  data_agendada: limpar(body.data_agendada || body.date, 20),
  hora_agendada: limpar(body.hora_agendada || body.time, 20),
  local: limpar(body.local || body.location, 220),
  observacoes_cliente: limpar(body.observacoes_cliente || body.notes, 1000),
  profissional_solicitada: limpar(body.profissional_solicitada, 180) || null,
  status: 'Aprovado',
  origem: 'site_massoterapiarj',
  recebido_em: new Date().toISOString()
};

const erros = [];
if (!payload.nome_cliente) erros.push('Nome do cliente é obrigatório.');
if (!payload.servico) erros.push('Serviço é obrigatório.');
if (!payload.data_agendada) erros.push('Data é obrigatória.');
if (!payload.hora_agendada) erros.push('Horário é obrigatório.');
if (!payload.whatsapp && !payload.telefone && !payload.email && !payload.telegram) erros.push('Informe ao menos um contato.');
if (payload.data_agendada && payload.hora_agendada && isTooSoonOrPast(payload.data_agendada, payload.hora_agendada)) {
  erros.push(`Horário deve ter pelo menos ${LEAD_MINUTES} minutos de antecedência no fuso de Brasília.`);
}

if (erros.length) {
  throw new Error(`VALIDACAO: ${erros.join(' ')}`);
}

return [{ json: payload }];

const agendamento = $json.agendamento || $json;
const data = agendamento.data_agendada ? String(agendamento.data_agendada).slice(0, 10).split('-').reverse().join('/') : '-';
const hora = agendamento.hora_agendada ? String(agendamento.hora_agendada).slice(0, 5) : '-';
const contato = agendamento.whatsapp || agendamento.telefone || agendamento.email || agendamento.telegram || '-';
const valor = (v, fallback = '-') => v == null || v === '' ? fallback : String(v);
const normalizarTelefone = (valor) => {
  const digitos = String(valor || '').replace(/\D/g, '');
  if (!digitos) return '';
  if (digitos.startsWith('55') && (digitos.length === 12 || digitos.length === 13)) return digitos;
  if (digitos.length === 10 || digitos.length === 11) return `55${digitos}`;
  return digitos;
};

const linhasTelegram = [
  'Novo agendamento recebido - Massoterapia RJ',
  '',
  `Codigo: ${agendamento.codigo || agendamento.id_agendamento || '-'}`,
  `Cliente: ${agendamento.nome_cliente || '-'}`,
  `Contato: ${contato}`,
  `Servico: ${agendamento.servico || '-'}`,
  `Data: ${data}`,
  `Horario: ${hora}`,
  `Local: ${agendamento.local || '-'}`,
  `Status: ${agendamento.status || 'Aprovado'}`
];

if (agendamento.observacoes_cliente) {
  linhasTelegram.push('', `Observacoes: ${agendamento.observacoes_cliente}`);
}

const linhasWhatsApp = [
  `Olá, ${agendamento.nome_cliente || 'tudo bem'}!`,
  '',
  'Recebemos seu pedido de agendamento na Massoterapia RJ.',
  '',
  `Código: ${agendamento.codigo || agendamento.id_agendamento || '-'}`,
  `Serviço: ${agendamento.servico || '-'}`,
  `Data: ${data}`,
  `Horário: ${hora}`,
  `Local: ${agendamento.local || '-'}`,
  '',
  'Status: Aprovado.',
  'A equipe recebeu seu agendamento aprovado e acompanhará pelo sistema.'
];

const emailHtml = `<div style="font-family:Arial,sans-serif;max-width:620px;margin:0 auto;color:#2a2520;line-height:1.6">
  <h2 style="color:#946b40">Pedido de agendamento recebido</h2>
  <p>Olá, ${valor(agendamento.nome_cliente, 'tudo bem')}.</p>
  <p>Recebemos seu pedido na Massoterapia RJ. Ele está com status <strong>Aprovado</strong> no sistema.</p>
  <table style="border-collapse:collapse;width:100%;margin:18px 0">
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Código</td><td style="padding:8px;border:1px solid #e5daca">${valor(agendamento.codigo || agendamento.id_agendamento)}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Serviço</td><td style="padding:8px;border:1px solid #e5daca">${valor(agendamento.servico)}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Data</td><td style="padding:8px;border:1px solid #e5daca">${data}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Horário</td><td style="padding:8px;border:1px solid #e5daca">${hora}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Local</td><td style="padding:8px;border:1px solid #e5daca">${valor(agendamento.local)}</td></tr>
    <tr><td style="padding:8px;border:1px solid #e5daca;font-weight:bold">Contato informado</td><td style="padding:8px;border:1px solid #e5daca">${valor(contato)}</td></tr>
  </table>
  ${agendamento.observacoes_cliente ? `<p><strong>Observações enviadas:</strong><br>${valor(agendamento.observacoes_cliente)}</p>` : ''}
  <p>A equipe acompanha este agendamento pelo sistema e entrará em contato se precisar ajustar algo.</p>
  <div style="margin-top:22px;padding-top:16px;border-top:1px solid #e5daca;font-size:14px;color:#5f5145">
  <p><strong>Mensagem da equipe:</strong></p>
  <p>Este é um e-mail automático enviado pelo sistema de agendamento da Massoterapia RJ com os dados da sua solicitação preenchidos.</p>
  <p><strong>⚠️ Por favor, não responda este e-mail.</strong></p>
  <p>Para alterações de horário, dúvidas ou suporte ao seu agendamento, entre em contato diretamente pelo WhatsApp oficial do site:</p>
  <p><strong>📲 WhatsApp Massoterapia RJ: (21) 98203-3272</strong></p>
  <p><strong>Massoterapia RJ</strong><br>Av. Princesa Isabel, 323 – Sala 1007<br>Copacabana – Rio de Janeiro</p>
</div>
</div>`;

return [{
  json: {
    ...$json,
    telegram_text: linhasTelegram.join('\n'),
    whatsapp_number: normalizarTelefone(agendamento.whatsapp || agendamento.telefone),
    whatsapp_text: linhasWhatsApp.join('\n'),
    email_subject: 'Recebemos seu pedido de agendamento - Massoterapia RJ',
    email_html: emailHtml
  }
}];

const destinos = String($env.TELEGRAM_CHAT_IDS || $env.TELEGRAM_CHAT_ID || '')
  .split(',')
  .map((id) => id.trim())
  .filter(Boolean);

return destinos.map((telegram_chat_id) => ({
  json: {
    ...$json,
    telegram_chat_id
  }
}));
